using System.Text.Json;
using DynamicFrontline.Core;
using DynamicFrontline.Frontline;
using DynamicFrontline.Frontline.Rules023;
using static Fixtures023;

var output = args.FirstOrDefault() ?? "artifacts/prototype023/tests"; Directory.CreateDirectory(output);
var results = new List<object>(); int failed = 0;
void Test(string name, Action body) { try { body(); results.Add(new { name, passed = true }); Console.WriteLine("PASS " + name); } catch (Exception e) { failed++; results.Add(new { name, passed = false, error = e.ToString() }); Console.WriteLine("FAIL " + name + ": " + e.Message); } }
void Assert(bool yes, string message = "assertion") { if (!yes) throw new Exception(message); }
void Near(double a, double b, double tolerance = 1e-7) { Assert(Math.Abs(a-b) <= tolerance, $"{a:R} != {b:R}"); }
void Reject(Action action) { try { action(); } catch (ArgumentException) { return; } throw new Exception("Expected rejection"); }

Test("configuration finite validation and immutable rules hash", () => { var c = new Rules023Config(); c.Validate(); Assert(c.Hash.Length==64); Reject(()=> (c with { A=.02 }).Validate()); Reject(()=> (c with { Dominance=1 }).Validate()); Reject(()=> (c with { Ramp=double.NaN }).Validate()); Reject(()=> (Infantry with { BaseMaxStress=0 }).Validate()); });
